"""Generate modern .pa.yaml for compilation by Microsoft's live authoring service."""
from pathlib import Path
import yaml,re
out=Path('power-platform/canvas-studio');out.mkdir(parents=True,exist_ok=True)
def write(name,value):(out/(name+'.pa.yaml')).write_text(yaml.safe_dump(value,allow_unicode=True,sort_keys=False,width=2000))
T='=RGBA(20,45,51,1)';G='=RGBA(8,127,112,1)';M='=RGBA(90,111,120,1)';W='=Color.White'
def ctrl(name,kind,props,children=None,variant=None):
 d={'Control':kind}
 if variant:d['Variant']=variant
 d['Properties']=props
 if children is not None:d['Children']=children
 return {name:d}
def label(n,text,y,h=28,size=13,**extra):return ctrl(n,'Label',{'Text':text,'X':'=Max(20,(Parent.Width-350)/2)','Y':f'={y}','Width':'=Min(350,Parent.Width-40)','Height':f'={h}','Size':f'={size}','Color':T,**extra})
def button(n,text,y,action,**extra):return ctrl(n,'Classic/Button',{'Text':text,'X':'=Max(20,(Parent.Width-350)/2)','Y':f'={y}','Width':'=Min(350,Parent.Width-40)','Height':'=46','Fill':G,'Color':W,'Size':'=14','OnSelect':action,**extra})
def field(n,hint,y,default='=""',**extra):return ctrl(n,'Classic/TextInput',{'Default':default,'HintText':hint,'AccessibleLabel':hint,'X':'=Max(20,(Parent.Width-350)/2)','Y':f'={y}','Width':'=Min(350,Parent.Width-40)','Height':'=42','Size':'=13','BorderColor':'=RGBA(200,215,216,1)',**extra})
def head(title,subtitle):
 title_id=re.sub(r'[^A-Za-z0-9]','',title)
 return [label(title_id+'Title','="'+title+'"',22,42,24,FontWeight='=FontWeight.Semibold'),label(title_id+'Subtitle','="'+subtitle+'"',66,38,11,Color=M)]
def screen(name,children,props=None):
 # Phone Canvas uses two authoring units per CSS pixel in the native player.
 # Keep the design's readable sizes while retaining responsive parent dimensions.
 layout_keys={'X','Y','Width','Height','Size','TemplateSize','TemplatePadding','LayoutMinHeight','LayoutMinWidth','FocusedBorderThickness'}
 def phone_units(items):
  for item in items:
   c=next(iter(item.values()))
   if c['Control'] in {'Label','Gallery','Image','Classic/Icon'}:
    c['Properties']['TabIndex']='=0'
   if c['Control']=='Label':c['Properties']['FocusedBorderThickness']='=2'
   for key,value in c.get('Properties',{}).items():
    if key in layout_keys and isinstance(value,str):
     c['Properties'][key]=re.sub(r'(?<![\w.])(\d+(?:\.\d+)?)',lambda m:m.group(0) if m.string[max(0,m.start()-1):m.start()]=='/' else str(float(m.group(0))*2).removesuffix('.0'),value)
   phone_units(c.get('Children',[]))
 phone_units(children)
 def local_events(items):
  for item in items:
   c=next(iter(item.values()))
   for key,value in c.get('Properties',{}).items():
    if key.startswith('On') and isinstance(value,str):
     c['Properties'][key]=re.sub(r'Reset\((HumanConfirm|ReferenceInput|SupplierInput|QuantityInput|ExpectedInput|NoteInput|SiteInput|UnitInput)\);\s*','',value)
   local_events(c.get('Children',[]))
 local_events(children)
 props=dict(props or {})
 if name=='RegisterScreen':props['OnVisible']='=Reset(ReferenceInput); Reset(SupplierInput); Reset(QuantityInput); Reset(ExpectedInput); Reset(NoteInput); Reset(SiteInput); Reset(UnitInput)'
 if name=='ReviewScreen':props['OnVisible']='=Reset(HumanConfirm)'
 # A scrollable viewport keeps every action reachable on smaller phones.
 body=ctrl(name+'Body','GroupContainer',{'Width':'=Parent.Width','Height':'=2000','LayoutMinHeight':'=2000','LayoutMinWidth':'=0','FillPortions':'=0','DropShadow':'=DropShadow.None'},children,'ManualLayout')
 viewport=ctrl(name+'Viewport','GroupContainer',{'Width':'=Parent.Width','Height':'=Parent.Height','LayoutDirection':'=LayoutDirection.Vertical','LayoutOverflowY':'=LayoutOverflow.Scroll','LayoutOverflowX':'=LayoutOverflow.Hide','DropShadow':'=DropShadow.None'},[body],'AutoLayout')
 write(name,{'Screens':{name:{'Properties':{'Fill':'=RGBA(246,249,248,1)',**(props or {})},'Children':[viewport]}}})
write('App',{'App':{'Properties':{'Theme':'=PowerAppsTheme','StartScreen':'=Overzicht','MinScreenWidth':'=320','MinScreenHeight':'=320','OnStart':'=Set(varBusy,false); Set(varPhoto,Blank()); Set(varAiPhoto,Blank()); Set(varRawOcr,""); Set(varAiUsed,false)'}}})
